// Public: report panel app (server flow). Fetches the audit run, then renders
// the interactive panel: dual-condition filter (severity + rule prefix),
// per-rule group chips, and a per-row "copy fix snippet" button.
// Pure logic lives in ./filter.js and ./format.js; HTML rendering in
// ../src/render-panel.js. This module is the served (http) entry; the
// offline/file:// deliverable inlines the same logic in index.html.
import { applyFilter, groupByRule } from './filter.js'
import { formatCounts, countTotal, severityLabel, copyFixSnippet } from './format.js'
import { escapeHtml, renderGroupsHtml, renderRowsHtml } from '../src/render-panel.js'

const SEVERITY_CHOICES = [
  { value: 'info', label: '全部' },
  { value: 'warn', label: '警告及以上' },
  { value: 'error', label: '仅错误' },
]

// Copy with a file://-safe fallback (Clipboard API needs a secure context).
function copyText(text) {
  if (navigator.clipboard && window.isSecureContext) {
    return navigator.clipboard.writeText(text)
  }
  const ta = document.createElement('textarea')
  ta.value = text
  ta.style.position = 'fixed'
  ta.style.top = '-1000px'
  document.body.appendChild(ta)
  ta.select()
  let ok = false
  try { ok = document.execCommand('copy') } catch { ok = false }
  document.body.removeChild(ta)
  return Promise.resolve(ok)
}

function cardsHtml(summary) {
  return ['error', 'warn', 'info'].map(sev => (
    `<div class="card card-${sev}"><span class="count" data-sev="${sev}">${summary[`${sev}s`] ?? 0}</span>`
    + `<span class="label">${severityLabel(sev)}</span></div>`
  )).join('\n')
}

/** Build the interactive panel DOM and wire up events. Pure of network I/O. */
export function mount(root, report) {
  const findings = report.findings ?? []
  const summary = report.summary ?? {}
  const state = { minSeverity: 'info', rulePrefix: '' }

  root.innerHTML = `
    <h1>审计报告：${escapeHtml(report.pkg ?? '')} v${escapeHtml(report.version ?? '')}</h1>
    <div id="summary-cards">${cardsHtml(summary)}</div>
    <div id="controls">
      <label>级别
        <select id="min-severity">
          ${SEVERITY_CHOICES.map(c => `<option value="${c.value}">${c.label}</option>`).join('')}
        </select>
      </label>
      <label>规则前缀
        <input id="rule-prefix" type="text" placeholder="如 R1" />
      </label>
      <span id="summary-text">${formatCounts(summary)} · 共 ${countTotal(summary)} 条</span>
    </div>
    <div id="groups"></div>
    <table id="findings"><thead><tr><th>规则</th><th>级别</th><th>说明</th><th>文件</th><th>操作</th></tr></thead>
    <tbody id="rows"></tbody></table>
  `

  const rowsEl = root.querySelector('#rows')
  const groupsEl = root.querySelector('#groups')
  const sel = root.querySelector('#min-severity')
  const prefix = root.querySelector('#rule-prefix')

  function render() {
    const filtered = applyFilter(findings, state)
    rowsEl.innerHTML = renderRowsHtml(filtered)
    groupsEl.innerHTML = renderGroupsHtml(groupByRule(filtered))
  }

  sel.addEventListener('change', () => { state.minSeverity = sel.value; render() })
  prefix.addEventListener('input', () => { state.rulePrefix = prefix.value.trim(); render() })
  rowsEl.addEventListener('click', (e) => {
    const btn = e.target.closest('.copy-btn')
    if (!btn) return
    const snippet = copyFixSnippet({ rule: btn.dataset.rule, file: btn.dataset.file })
    copyText(snippet).then(() => {
      const old = btn.textContent
      btn.textContent = '已复制'
      setTimeout(() => { btn.textContent = old }, 1200)
    })
  })

  render()
}

export async function boot(root = document.getElementById('app')) {
  const res = await fetch('/api/audit')
  const run = await res.json()
  mount(root, run.report)
}

// Served entry point: render the live audit when loaded as a module over http.
if (typeof document !== 'undefined') {
  boot().catch(err => console.error('[relaudit] panel boot failed:', err))
}
